package com.fixmer.mared.technology.server.setup;
import com.fixmer.mared.gui2.framework.screen.MaredScreen;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.*;import net.minecraft.network.chat.Component;import java.util.*;
/** Native online server roles and bounded actor audit. No host paths or external windows. */
public final class ServerAccessScreen88 extends MaredScreen {
 private final Screen previous;private EditBox target;private Button role,grant,revoke,online;private int onlineIndex;private String selected="OBSERVER",saved="";private int left,w,top,scroll,maxScroll;
 public ServerAccessScreen88(Screen previous){super(tr("title"));this.previous=previous;}private static Component tr(String key,Object...args){return Component.translatable("mared.access88."+key,args);}
 private Button button(String key,int x,int y,int width,Runnable fn){return addRenderableWidget(Button.builder(tr(key),b->fn.run()).bounds(x,y,width,20).build());}
 @Override protected void init(){if(target!=null)saved=target.getValue();w=Math.max(250,Math.min(680,width-24));left=(width-w)/2;target=addRenderableWidget(new EditBox(font,left,47,w,20,tr("target")));target.setMaxLength(36);target.setValue(saved);target.setHint(Component.literal("xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"));online=button("online",left,71,w,this::chooseOnline);int bw=(w-8)/3;role=button("role."+selected,left,95,bw,()->{List<String> roles=List.of("OBSERVER","PREPARER","PUBLISHER","RESTARTER","MAINTAINER");selected=roles.get((roles.indexOf(selected)+1)%roles.size());role.setMessage(tr("role."+selected));});grant=button("grant",left+bw+4,95,bw,()->confirm(false));revoke=button("revoke",left+2*(bw+4),95,bw,()->confirm(true));top=123;button("back",left,height-27,w,this::onClose);tick();}
 private void chooseOnline(){List<String> players=ServerAccessService88.view().getOrDefault("players","").lines().filter(v->v.matches("[a-f0-9-]{36}=[A-Za-z0-9_]{1,16}")).toList();if(players.isEmpty())return;String[] p=players.get(Math.floorMod(onlineIndex++,players.size())).split("=");target.setValue(p[0]);online.setMessage(tr("online_selected",p[1]));}
 private void confirm(boolean remove){saved=target.getValue();minecraft.setScreen(new ConfirmScreen(yes->{minecraft.setScreen(this);if(yes)ServerAccessService88.change(saved,remove?"NONE":selected);},tr(remove?"revoke":"grant"),tr("confirm",saved,tr("role."+(remove?"NONE":selected)))));}
 @Override public void tick(){ServerAccessService88.poll();boolean edit=ServerAccessService88.manage()&&!ServerAccessService88.busy();target.setEditable(edit);online.active=role.active=grant.active=revoke.active=edit;}
 @Override public boolean isPauseScreen(){return false;}@Override public void onClose(){minecraft.setScreen(previous);}@Override public boolean mouseScrolled(double x,double y,double dx,double dy){scroll=Math.max(0,Math.min(maxScroll,scroll+(int)(-dy*24)));return true;}
 @Override public void render(GuiGraphics g,int mx,int my,float dt){g.fill(0,0,width,height,0xF0151820);g.drawCenteredString(font,title,width/2,9,0xFFFFFFFF);g.drawCenteredString(font,tr("result."+ServerAccessService88.result()),width/2,23,0xFFCCD0DC);g.drawString(font,tr("target"),left,36,0xFFCCD0DC,false);var d=ServerAccessService88.view();List<Component> text=new ArrayList<>();text.add(tr("your_role",tr("role."+d.getOrDefault("role","NONE")),d.getOrDefault("revision","—")));text.add(tr("description."+selected));text.add(tr("scope"));if(d.containsKey("subjects")){for(String line:d.get("subjects").split("\n")){String[] p=line.split("=");if(p.length==2)text.add(tr("member",p[0],tr("role."+p[1])));}}text.add(tr("audit"));if(d.containsKey("audit"))for(String line:d.get("audit").split("\n")){String[] p=line.split("\\|",-1);if(p.length==8)text.add(tr("audit_row",p[0],p[2],tr("action."+p[4]),tr("outcome."+p[5]),p[7],p[3]));}List<net.minecraft.util.FormattedCharSequence> lines=new ArrayList<>();for(Component c:text)lines.addAll(font.split(c,w-6));int row=font.lineHeight+3,bottom=height-35;maxScroll=Math.max(0,lines.size()*row-Math.max(0,bottom-top));scroll=Math.min(scroll,maxScroll);if(bottom>top){g.enableScissor(left,top,left+w,bottom);int y=top-scroll;for(var line:lines){if(y+row>=top&&y<bottom)g.drawString(font,line,left,y,0xFFCCD0DC,false);y+=row;}g.disableScissor();}super.render(g,mx,my,dt);}
}
